using System;
using UnityEngine;
using UnityEngine.UI;

namespace WeirdLand.Unity
{
    /// <summary>
    /// Binds the visual parts (prefabs, colours, timings) the screens use, so placeholder art can be swapped later.
    /// Generated by WeirdLand/Build Prefabs (tools/unity.sh prefabs); colour and timing edits survive regeneration.
    /// </summary>
    [CreateAssetMenu(menuName = "WeirdLand/Visual Catalog", fileName = "VisualCatalog")]
    public class VisualCatalog : ScriptableObject
    {
        public const string ResourcePath = "VisualCatalog";

        [Header("Prefabs")]
        public CardView Card;
        public FighterView Fighter;
        public StatusChip StatusChip;
        public Button Button;
        public IntentBubble IntentBubble;

        [Header("Colours")]
        public Color AttackCard = new Color32(0xC8, 0x55, 0x3D, 0xFF);
        public Color DefenseCard = new Color32(0x3D, 0x7E, 0xC8, 0xFF);
        public Color BothCard = new Color32(0x7D, 0x5B, 0xA6, 0xFF);
        public Color UserTeam = new Color32(0x2E, 0x6F, 0xD8, 0xFF);
        public Color EnemyTeam = new Color32(0xD8, 0x3A, 0x2E, 0xFF);
        public Color Keeper = new Color32(0xE0, 0xB0, 0x00, 0xFF);
        public Color Background = new Color32(0x1E, 0x5B, 0x2E, 0xFF);

        [Header("Animation")]
        public AnimTimings Timings = new AnimTimings();

        public static VisualCatalog Load()
        {
            var cat = Resources.Load<VisualCatalog>(ResourcePath);
            if (cat == null)
                throw new InvalidOperationException(
                    "VisualCatalog not found at Resources/" + ResourcePath +
                    ".asset. Generate it with WeirdLand/Build Prefabs (tools/unity.sh prefabs).");
            return cat;
        }
    }
}
